  // Contact
  "contact.title": { en: "Contact", af: "Kontak", fr: "Contact", es: "Contacto", de: "Kontakt", pt: "Contacto", it: "Contatto", nl: "Contact", zu: "Xhumana", xh: "Qhagamshelana", st: "Ikgokaganyo", ar: "اتصل بنا", zh: "联系我们", hi: "संपर्क करें" },
  "contact.subtitle": { en: "Ready to connect? Choose your preferred way to reach out. We're here to help with questions, feedback, or collaboration opportunities.", af: "Gereed om te verbind? Kies jou voorkeurmanier om ons te kontak. Ons is hier om te help met vrae, terugvoer of samewerkingsgeleenthede.", fr: "Prêt à nous contacter ? Choisissez votre moyen de communication préféré.", es: "¿Listo para conectar? Elige tu forma preferida de comunicarte. Estamos aquí para ayudar con preguntas, comentarios u oportunidades de colaboración.", de: "Bereit, Kontakt aufzunehmen? Wählen Sie Ihre bevorzugte Kontaktmethode.", pt: "Pronto para conectar? Escolha a sua forma preferida de nos contactar.", it: "Pronto a connetterti? Scegli il tuo modo preferito per contattarci.", nl: "Klaar om contact op te nemen? Kies uw voorkeursmethode.", zu: "Ulungele ukuxhumana? Khetha indlela oyithandayo yokuxhumana nathi.", xh: "Ulungile ukuqhagamshelana? Khetha indlela oyithandayo yokufikelela kuthi.", st: "U lokela ho hokahana? Khetha tsela eo u e ratang ea ho fihla ho rona.", ar: "مستعد للتواصل؟ اختر طريقتك المفضلة للاتصال بنا.", zh: "准备好联系了吗？选择您喜欢的联系方式。我们随时为您解答问题、提供反馈或合作机会。", hi: "संपर्क करने के लिए तैयार हैं? अपना पसंदीदा तरीका चुनें।" },
