  "contact.whatsappDesc": { en: "Start a chat with our team on WhatsApp for quick questions and support.", af: "Begin 'n klets met ons span op WhatsApp vir vinnige vrae en ondersteuning.", fr: "Démarrez une discussion avec notre équipe sur WhatsApp pour des questions rapides et du support.", es: "Inicia un chat con nuestro equipo en WhatsApp para preguntas rápidas y soporte.", de: "Starten Sie einen Chat mit unserem Team auf WhatsApp für schnelle Fragen und Support.", pt: "Inicie uma conversa com a nossa equipa no WhatsApp para perguntas rápidas e suporte.", it: "Avvia una chat con il nostro team su WhatsApp per domande rapide e supporto.", nl: "Start een chat met ons team op WhatsApp voor snelle vragen en ondersteuning.", zu: "Qala ingxoxo nethimba lethu ku-WhatsApp ngemibuzo esheshayo nosizo.", xh: "Qala incoko neqela lethu ku-WhatsApp ngemibuzo ekhawulezayo nenkxaso.", st: "Qala puisano le sehlopha sa rona ho WhatsApp bakeng sa lipotso tse potlakileng le tshehetso.", ar: "ابدأ محادثة مع فريقنا على واتساب للأسئلة السريعة والدعم.", zh: "在WhatsApp上与我们的团队聊天，获取快速解答和支持。", hi: "त्वरित प्रश्नों और सहायता के लिए WhatsApp पर हमारी टीम से चैट शुरू करें।" },
  "contact.emailDesc": { en: "Drop us a line anytime. We read every email and typically respond within 24 hours.", af: "Stuur ons enige tyd 'n e-pos. Ons lees elke e-pos en reageer gewoonlik binne 24 uur.", fr: "Envoyez-nous un message à tout moment. Nous répondons généralement sous 24 heures.", es: "Escríbenos en cualquier momento. Leemos todos los correos y generalmente respondemos en 24 horas.", de: "Schreiben Sie uns jederzeit. Wir antworten in der Regel innerhalb von 24 Stunden.", pt: "Envie-nos uma mensagem a qualquer momento. Respondemos geralmente em 24 horas.", it: "Scrivici in qualsiasi momento. Rispondiamo generalmente entro 24 ore.", nl: "Stuur ons een bericht wanneer u wilt. We reageren doorgaans binnen 24 uur.", zu: "Sithumelele i-imeyili noma nini. Sivame ukuphendula phakathi kwamahora angu-24.", xh: "Sithumelele i-imeyile nanini na. Siphendula ngaphakathi kweeyure ezingama-24.", st: "Re romele e-mail nako efe kapa efe. Re araba ka mora lihora tse 24.", ar: "راسلنا في أي وقت. نرد عادة خلال 24 ساعة.", zh: "随时给我们发送邮件。我们阅读每封邮件，通常在24小时内回复。", hi: "कभी भी हमें लिखें। हम आमतौर पर 24 घंटे में जवाब देते हैं।" },
  "contact.phoneDesc": { en: "Call us for urgent matters, interview requests, or technical support.", af: "Skakel ons vir dringende sake, onderhoudversoeke of tegniese ondersteuning.", fr: "Appelez-nous pour les urgences, demandes d'interview ou support technique.", es: "Llámanos para asuntos urgentes, solicitudes de entrevistas o soporte técnico.", de: "Rufen Sie uns bei dringenden Angelegenheiten oder technischem Support an.", pt: "Ligue-nos para assuntos urgentes ou suporte técnico.", it: "Chiamaci per questioni urgenti o supporto tecnico.", nl: "Bel ons voor dringende zaken of technische ondersteuning.", zu: "Sishayele ngezindaba eziphuthumayo noma ukwesekwa kwezobuchwepheshe.", xh: "Sitsalele ngemicimbi engxamisekileyo okanye inkxaso yobuchwephesha.", st: "Re letsetseng bakeng sa litaba tse potlakileng kapa ts'ehetso ea theknoloji.", ar: "اتصل بنا للأمور العاجلة أو الدعم الفني.", zh: "如有紧急事务、采访请求或技术支持，请致电我们。", hi: "तत्काल मामलों या तकनीकी सहायता के लिए हमें कॉल करें।" },
  "contact.youtubeDesc": { en: "Watch video episodes, behind-the-scenes content, and exclusive interviews.", af: "Kyk video-episodes, agter-die-skerms-inhoud en eksklusiewe onderhoude.", fr: "Regardez des épisodes vidéo, du contenu en coulisses et des interviews exclusives.", es: "Mira episodios en video, contenido detrás de escenas y entrevistas exclusivas.", de: "Sehen Sie Videoepisoden, Inhalte hinter den Kulissen und exklusive Interviews.", pt: "Assista a episódios em vídeo, conteúdo dos bastidores e entrevistas exclusivas.", it: "Guarda episodi video, contenuti dietro le quinte e interviste esclusive.", nl: "Bekijk video-afleveringen, content achter de schermen en exclusieve interviews.", zu: "Bukela iziqephu zevidiyo, okuqukethwe okungasemva kwezindaba nezingxoxo ezikhethekile.", xh: "Bukela iividiyo, umxholo ongasemva kwekhethini nodliwanondlebe olukhethekileyo.", st: "Sheba likotoana tsa livideo, litaba tse ka morao ho mokoloko le lipuisano tse khethehileng.", ar: "شاهد حلقات الفيديو والمحتوى خلف الكواليس والمقابلات الحصرية.", zh: "观看视频剧集、幕后内容和独家访谈。", hi: "वीडियो एपिसोड, पर्दे के पीछे की सामग्री और विशेष साक्षात्कार देखें।" },
  "contact.facebookDesc": { en: "Connect with fellow listeners, get episode updates, and join live discussions.", af: "Verbind met medekykers, kry episode-opdaterings en sluit aan by lewendige besprekings.", fr: "Connectez-vous avec d'autres auditeurs et participez aux discussions en direct.", es: "Conéctate con otros oyentes, recibe actualizaciones de episodios y únete a discusiones en vivo.", de: "Verbinden Sie sich mit anderen Zuhörern und nehmen Sie an Live-Diskussionen teil.", pt: "Conecte-se com outros ouvintes e participe de discussões ao vivo.", it: "Connettiti con altri ascoltatori e partecipa alle discussioni dal vivo.", nl: "Maak contact met andere luisteraars en neem deel aan live discussies.", zu: "Xhumana nabanye abalaleli futhi ujoyine izingxoxo bukhoma.", xh: "Dibanisa nabanye abamameli kwaye ujoyine iingxoxo eziphilayo.", st: "Hokahana le batheeletsi ba bang 'me u kenele lipuisano tsa ka nako ea sebele.", ar: "تواصل مع المستمعين الآخرين وانضم إلى المناقشات المباشرة.", zh: "与其他听众联系，获取剧集更新，参与实时讨论。", hi: "अन्य श्रोताओं से जुड़ें और लाइव चर्चाओं में शामिल हों।" },

