  // Landing page
  "land.badge": { en: "AudioVisual eBook Engine — powered by AI", af: "OudioVisuele eBoek-enjin — aangedryf deur KI", fr: "Moteur eBook AudioVisuel — propulsé par l'IA", es: "Motor de eBook AudioVisual — impulsado por IA", de: "AudioVisuelles eBook-Engine — angetrieben von KI", pt: "Motor de eBook AudioVisual — alimentado por IA", it: "Motore eBook AudioVisivo — alimentato dall'IA", nl: "AudioVisuele eBook-engine — aangedreven door AI", zu: "Injini ye-eBook e-AudioVisual — iqhutshwa yi-AI", xh: "Injini ye-eBook ye-AudioVisual — iqhutywa yi-AI", st: "Enjini ea e-eBook ea AudioVisual — e tsamaisoang ke AI", ar: "محرك الكتاب الإلكتروني السمعي البصري — مدعوم بالذكاء الاصطناعي", zh: "视听电子书引擎 — 由AI驱动", hi: "ऑडियोविज़ुअल ईबुक इंजन — AI द्वारा संचालित" },
  "land.hero1": { en: "Turn Any Topic Into a Researched", af: "Verander Enige Onderwerp in 'n", fr: "Transformez n'importe quel sujet en", es: "Convierte cualquier tema en un", de: "Verwandeln Sie jedes Thema in ein", pt: "Transforme qualquer tema num", it: "Trasforma qualsiasi argomento in un", nl: "Verander elk onderwerp in een", zu: "Guqula Noma Yisiphi Isihloko Sibe", xh: "Guqula Nawuphi na Umxholo Ube", st: "Fetola Sehlooho Sefe Kapa Sefe Ho Ba", ar: "حوّل أي موضوع إلى", zh: "将任何主题转化为", hi: "किसी भी विषय को बनाएं" },
  "land.hero2": { en: "AudioVisual eBook", af: "OudioVisuele eBoek", fr: "eBook AudioVisuel", es: "eBook AudioVisual", de: "AudioVisuelles eBook", pt: "eBook AudioVisual", it: "eBook AudioVisivo", nl: "AudioVisueel eBook", zu: "i-eBook ye-AudioVisual", xh: "i-eBook ye-AudioVisual", st: "eBook ea AudioVisual", ar: "كتاب إلكتروني سمعي بصري", zh: "视听电子书", hi: "ऑडियोविज़ुअल ईबुक" },
  "land.subtitle": {
    en: "Create AI-assisted eBooks with structured research, cinematic visuals, voice narration, background music, and export-ready formats for PDF, HTML, or ePub.",
    af: "Resonance ePublisher help skeppers, opvoeders, podcasters en besighede om idees te omskep in nagevorste hoofstukke, cinematiese beelde, vertelling, agtergrondmusiek en uitvoer-gereed digitale boeke.",
    fr: "Resonance ePublisher aide les créateurs, éducateurs, podcasteurs et entreprises à transformer leurs idées en chapitres documentés, visuels cinématographiques, narration, musique de fond et livres numériques prêts à l'export.",
    es: "Resonance ePublisher ayuda a creadores, educadores, podcasters y empresas a transformar ideas en capítulos investigados, imágenes cinematográficas, narración, música de fondo y libros digitales listos para exportar.",
    de: "Resonance ePublisher hilft Kreativen, Pädagogen, Podcastern und Unternehmen, Ideen in recherchierte Kapitel, filmische Bilder, Erzählung, Hintergrundmusik und exportbereite digitale Bücher zu verwandeln.",
    pt: "O Resonance ePublisher ajuda criadores, educadores, podcasters e empresas a transformar ideias em capítulos pesquisados, visuais cinematográficos, narração, música de fundo e livros digitais prontos para exportação.",
    it: "Resonance ePublisher aiuta creatori, educatori, podcaster e aziende a trasformare le idee in capitoli documentati, immagini cinematografiche, narrazione, musica di sottofondo e libri digitali pronti per l'esportazione.",
    nl: "Resonance ePublisher helpt makers, opvoeders, podcasters en bedrijven om ideeën om te zetten in onderzochte hoofdstukken, filmische beelden, vertelling, achtergrondmuziek en exportklare digitale boeken.",
    zu: "I-Resonance ePublisher isiza abadali, abafundisi, ama-podcaster, namabhizinisi ukuguqula imibono ibe yizahluko ezicwaningiwe, izithombe zefilimu, ukuxoxa, umculo wangaphambili, nezincwadi zedijithali ezilungele ukuthekelisa.",
    xh: "I-Resonance ePublisher inceda abadali, abafundisi, ama-podcaster, namashishini ukuguqula iingcamango zibe ziziqendu eziphandiweyo, imifanekiso yefilimu, ukubalisa, umculo wesiqalo, kunye neencwadi zedijithali ezilungele ukuthunyelwa ngaphandle.",
    st: "Resonance ePublisher e thusa baetsi, mesuoe, li-podcaster, le likhoebo ho fetola mehopolo hore e be likhaolo tse batlisisitsoeng, litšoantšo tsa filimi, pale, mmino oa morao, le libuka tsa dijithale tse lokileng ho romeloa.",
    ar: "يساعد Resonance ePublisher المبدعين والمعلمين ومقدمي البودكاست والشركات على تحويل الأفكار إلى فصول مدروسة ومرئيات سينمائية وسرد وموسيقى خلفية وكتب رقمية جاهزة للتصدير.",
    zh: "Resonance ePublisher 帮助创作者、教育者、播客和企业将想法转化为经过研究的章节、电影级视觉效果、旁白、背景音乐和可导出的数字书籍。",
    hi: "Resonance ePublisher रचनाकारों, शिक्षकों, पॉडकास्टरों और व्यवसायों को विचारों को शोधित अध्यायों, सिनेमाई दृश्यों, नैरेशन, बैकग्राउंड म्यूज़िक और निर्यात-तैयार डिजिटल पुस्तकों में बदलने में मदद करता है।",
  },
